import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Multistart simulator-guided insertion followed by bounded local descent."""
    import time

    n = workload.num_txns
    if n == 0:
        return 0, []

    deadline = time.monotonic() + 119.0
    construction_deadline = deadline - 22.0
    cache = {}

    def cost(seq):
        key = tuple(seq)
        value = cache.get(key)
        if value is None:
            value = workload.get_opt_seq_cost(list(seq))
            cache[key] = value
        return value

    best_seq = list(range(n))
    best_cost = cost(best_seq)

    starts = min(10, max(3, num_seqs))
    seed_order = [0] if n == 1 else [0, n - 1]
    stride = max(1, n // max(1, starts - 2))
    seed_order.extend(
        (2 + i * stride) % n for i in range(max(0, starts - 2))
    )

    seen = set()
    for seed in seed_order:
        if seed in seen or time.monotonic() >= construction_deadline:
            continue
        seen.add(seed)

        sequence = [seed]
        remaining = [txn for txn in range(n) if txn != seed]

        while remaining and time.monotonic() < construction_deadline:
            width = min(12, len(remaining))
            offset = (seed * 11 + len(sequence) * 7) % len(remaining)
            candidates = [
                remaining[(offset + j) % len(remaining)]
                for j in range(width)
            ]

            selected_txn = None
            selected_position = 0
            selected_cost = None

            for txn in candidates:
                if time.monotonic() >= construction_deadline:
                    break
                for position in range(len(sequence) + 1):
                    trial = (
                        sequence[:position]
                        + [txn]
                        + sequence[position:]
                    )
                    value = cost(trial)
                    if (
                        selected_cost is None
                        or value < selected_cost
                        or (
                            value == selected_cost
                            and (
                                selected_txn is None
                                or txn < selected_txn
                                or (
                                    txn == selected_txn
                                    and position < selected_position
                                )
                            )
                        )
                    ):
                        selected_cost = value
                        selected_txn = txn
                        selected_position = position

            if selected_txn is None:
                break

            sequence.insert(selected_position, selected_txn)
            remaining.remove(selected_txn)

        sequence.extend(remaining)
        value = cost(sequence)
        if value < best_cost:
            best_cost, best_seq = value, sequence

    # Preserve useful local transaction chains while relocating their
    # macro-position in the order.
    for _ in range(3):
        if time.monotonic() >= deadline:
            break

        improved = False
        for length in range(2, min(5, n) + 1):
            if improved or time.monotonic() >= deadline:
                break

            for start in range(n - length + 1):
                if time.monotonic() >= deadline:
                    break

                block = best_seq[start:start + length]
                remainder = best_seq[:start] + best_seq[start + length:]

                for target in range(len(remainder) + 1):
                    if time.monotonic() >= deadline:
                        break

                    candidate = (
                        remainder[:target] + block + remainder[target:]
                    )
                    value = cost(candidate)
                    if value < best_cost:
                        best_cost, best_seq = value, candidate
                        improved = True
                        break

                if improved:
                    break

        if not improved:
            break

    # Cheap boundary cleanup first.
    for _ in range(2):
        if time.monotonic() >= deadline:
            break

        improved = False
        for i in range(n - 1):
            if time.monotonic() >= deadline:
                break

            candidate = best_seq[:]
            candidate[i], candidate[i + 1] = candidate[i + 1], candidate[i]
            value = cost(candidate)

            if value < best_cost:
                best_cost, best_seq = value, candidate
                improved = True
                break

        if not improved:
            break

    # A reversal is a distinct precedence-changing move: unlike relocation it
    # changes the internal order of a conflict-coupled chain in one step.
    for _ in range(2):
        if time.monotonic() >= deadline:
            break

        improved = False
        for length in range(3, min(8, n) + 1):
            if improved or time.monotonic() >= deadline:
                break

            for start in range(n - length + 1):
                if time.monotonic() >= deadline:
                    break

                candidate = (
                    best_seq[:start]
                    + list(reversed(best_seq[start:start + length]))
                    + best_seq[start + length:]
                )
                value = cost(candidate)
                if value < best_cost:
                    best_cost, best_seq = value, candidate
                    improved = True
                    break

        if not improved:
            break

    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
